import type { Point, VesselId } from './types';

/**
 * Each vessel is defined as a closed region built from cubic bezier curves.
 * Only the right-hand half profile (from the rim down to the bottom center)
 * is authored; the left half is generated by mirroring, and the rim is
 * closed with a symmetric dip curve suggesting the far edge of the opening.
 * All coordinates are in the vessel's own local space: x is an offset from
 * the vertical center axis (positive = right), y grows downward from the
 * rim. This local space is also what crack generation operates in, so
 * cracks never need to know about on-screen pixel scale.
 */
interface RightProfileSeg {
  c1x: number;
  c1y: number;
  c2x: number;
  c2y: number;
  x: number;
  y: number;
}

export interface VesselSpec {
  id: VesselId;
  label: string;
  topHalfWidth: number;
  topY: number;
  /** Control point offset/height used to close the rim curve across the top. */
  rimDipX: number;
  rimDipY: number;
  rightProfile: RightProfileSeg[];
}

