export const VESSEL_ORDER: VesselId[] = ['bowl', 'plate', 'vase'];

export interface VesselBounds {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
  width: number;
  height: number;
  midY: number;
}

const boundsCache = new Map<VesselId, VesselBounds>();

/**
 * Cubic bezier curves stay within the convex hull of their control points,
 * so scanning start/control/end points of every segment yields a safe
 * (if slightly generous) bounding box without sampling the curve itself.
 */
export function getBounds(spec: VesselSpec): VesselBounds {
  const cached = boundsCache.get(spec.id);
  if (cached) return cached;

  let maxX = spec.topHalfWidth;
  let minY = spec.topY;
  let maxY = spec.topY;

  const consider = (x: number, y: number): void => {
    if (Math.abs(x) > maxX) maxX = Math.abs(x);
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  };

  for (const seg of spec.rightProfile) {
    consider(seg.c1x, seg.c1y);
    consider(seg.c2x, seg.c2y);
    consider(seg.x, seg.y);
  }
  consider(spec.rimDipX, spec.rimDipY);

  const bounds: VesselBounds = {
    minX: -maxX,
    maxX,
    minY,
    maxY,
    width: maxX * 2,
    height: maxY - minY,
    midY: (minY + maxY) / 2,
  };
  boundsCache.set(spec.id, bounds);
  return bounds;
}

export interface VesselTransform {
  cx: number;
  cy: number;
  scale: number;
}

/** Fits the vessel's own bounding box into the given canvas area. */
export function computeTransform(
  canvasW: number,
  canvasH: number,
  spec: VesselSpec,
  fill = 0.78,
): VesselTransform {
  const bounds = getBounds(spec);
  const scale = Math.min((canvasW * fill) / bounds.width, (canvasH * fill) / bounds.height);
  return { cx: canvasW / 2, cy: canvasH / 2, scale };
}

export function toCanvasPoint(p: Point, t: VesselTransform, bounds: VesselBounds): Point {
  return { x: t.cx + p.x * t.scale, y: t.cy + (p.y - bounds.midY) * t.scale };
}

/** Generic builder: mapX/mapY convert local vessel coordinates into whatever
 * target space is needed (raw local space for hit-testing, or canvas pixel
 * space for drawing). Sharing this keeps the two paths perfectly consistent. */
function buildOutline(spec: VesselSpec, mapX: (x: number) => number, mapY: (y: number) => number): Path2D {
  const path = new Path2D();
  path.moveTo(mapX(spec.topHalfWidth), mapY(spec.topY));
  for (const seg of spec.rightProfile) {
    path.bezierCurveTo(mapX(seg.c1x), mapY(seg.c1y), mapX(seg.c2x), mapY(seg.c2y), mapX(seg.x), mapY(seg.y));
  }
  const n = spec.rightProfile.length;
  for (let i = n - 1; i >= 0; i--) {
    const seg = spec.rightProfile[i]!;
    const prevSeg = i > 0 ? spec.rightProfile[i - 1]! : null;
    const endX = prevSeg ? -prevSeg.x : -spec.topHalfWidth;
    const endY = prevSeg ? prevSeg.y : spec.topY;
    path.bezierCurveTo(mapX(-seg.c2x), mapY(seg.c2y), mapX(-seg.c1x), mapY(seg.c1y), mapX(endX), mapY(endY));
  }
  path.bezierCurveTo(
    mapX(-spec.rimDipX),
    mapY(spec.rimDipY),
    mapX(spec.rimDipX),
    mapY(spec.rimDipY),
    mapX(spec.topHalfWidth),
    mapY(spec.topY),
  );
  path.closePath();
  return path;
}

/** Path2D in canvas pixel space, ready to fill/stroke/clip on screen. */
export function buildCanvasPath(spec: VesselSpec, t: VesselTransform): Path2D {
  const bounds = getBounds(spec);
  return buildOutline(
    spec,
    (x) => t.cx + x * t.scale,
    (y) => t.cy + (y - bounds.midY) * t.scale,
  );
}

const containCache = new Map<VesselId, Path2D>();
const hitCache = new Map<VesselId, Path2D>();

/** Exact silhouette in local space, used to keep generated cracks inside the vessel. */
export function getContainPath(spec: VesselSpec): Path2D {
  let path = containCache.get(spec.id);
  if (!path) {
    path = buildOutline(
      spec,
      (x) => x,
      (y) => y,
    );
    containCache.set(spec.id, path);
  }
  return path;
}

/** Slightly enlarged silhouette (in local space) used only for pointer hit
 * testing, so mobile taps near the edge still register (per requirements). */
export function getHitPath(spec: VesselSpec): Path2D {
  let path = hitCache.get(spec.id);
  if (!path) {
    const bounds = getBounds(spec);
    const expand = 1.09;
    path = buildOutline(
      spec,
      (x) => x * expand,
      (y) => bounds.midY + (y - bounds.midY) * expand,
    );
    hitCache.set(spec.id, path);
  }
  return path;
}

// A detached 1x1 canvas used purely for Path2D geometry queries
// (isPointInPath does not depend on the canvas's actual pixel size).
const geometryCanvas = document.createElement('canvas');
geometryCanvas.width = 1;
geometryCanvas.height = 1;
const geometryCtx = geometryCanvas.getContext('2d')!;

export function isInside(path: Path2D, x: number, y: number): boolean {
  return geometryCtx.isPointInPath(path, x, y);
}

/** Converts a canvas pixel point into the vessel's local coordinate space. */
export function toLocalPoint(px: number, py: number, t: VesselTransform, bounds: VesselBounds): Point {
  return { x: (px - t.cx) / t.scale, y: (py - t.cy) / t.scale + bounds.midY };
}
